ORDER BY slot_no, trip_no

SELECT EXISTS (
    SELECT 1 FROM hd_timetable
    WHERE route_no = #{routeNo} AND day_type = #{dayType}
      AND slot_no = #{slotNo} AND trip_no = #{tripNo}
)

